// Generated by the platform from the OpenAPI contract (ADR-0016). Do not edit: it follows the design (C3).

import { call } from './client-runtime'
export { ApiError } from './client-runtime'

export interface RealizarTransferenciaRequest {
  /** text(var,10,iso8859-1) */
  cuentaOrigen: string
  /** text(var,10,iso8859-1) */
  cuentaDestino: string
  /** decimal(11,2,signed) */
  monto: number
  /** text(fixed,3,iso8859-1) */
  tipo: string
}

export interface RealizarTransferenciaResponse {
  /** text(var,40,utf8) */
  mensaje: string
  /** text(var,8,utf8) */
  comision: string
  /** integer(32,signed) */
  numero: number
}

export interface ConsultarComprobanteRequest {
  /** integer(32,signed) */
  numero: number
}

export interface ConsultarComprobanteResponse {
  /** text(var,11,utf8) */
  numero: string
  /** text(var,12,utf8) */
  monto: string
}

export interface Api {
  /** Transfers an amount between two active accounts. It trims the account numbers and rejects equal accounts. It validates origin (exists, active) and destination (exists, active), calculates the commission (flat 0.50 up to 1000.00, otherwise 0.1% rounded half away from zero, cap 5.00, then +1.00 for type INM) and checks that the balance covers amount plus commission. It then debits the origin by amount plus commission, credits the destination by the amount, records the transfer with the next number and commits everything in one transaction. (rules RULE-001, RULE-002, RULE-003, RULE-005, RULE-006, RULE-007, RULE-008, RULE-009) */
  realizarTransferencia(request: RealizarTransferenciaRequest): Promise<RealizarTransferenciaResponse>
  /** Returns the receipt of a transfer: the requested number as text and the amount stored for it formatted with two decimals ('0.00'). If the transfer does not exist, the amount is an empty string and no error is raised. (rules RULE-004) */
  consultarComprobante(request: ConsultarComprobanteRequest): Promise<ConsultarComprobanteResponse>
}

/** The client over fetch; `baseUrl` is where the backend runs (same origin by default). */
export function createApi(baseUrl = '', fetchImpl: typeof fetch = (input, init) => fetch(input, init)): Api {
  return {
    realizarTransferencia: (request) => call<RealizarTransferenciaResponse>(fetchImpl, baseUrl, 'POST', '/api/transferencias/transferencias', request, true),
    consultarComprobante: (request) => call<ConsultarComprobanteResponse>(fetchImpl, baseUrl, 'GET', '/api/transferencias/transferencias/{numero}/comprobante', request, false),
  }
}
