import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Badge,
  Alert,
  KeyBar,
  Modal,
} from '@nexti/ds';

type Errors = {
  txtCuentaOrigen?: string;
  txtCuentaDestino?: string;
  txtMonto?: string;
};

type Mensaje = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null;

const TIPOS = [
  { value: '', label: 'Seleccione (opcional)' },
  { value: 'PRO', label: 'PRO' },
  { value: 'INM', label: 'INM' },
];

function parseMonto(raw: string): number {
  return Number(raw.replace(',', '.'));
}

function formatUsd(n: number): string {
  return (
    'USD ' +
    n.toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
  );
}

export default function Transferencia({ navigate }: { navigate: (to: string) => void }) {
  const [cuentaOrigen, setCuentaOrigen] = useState('');
  const [cuentaDestino, setCuentaDestino] = useState('');
  const [monto, setMonto] = useState('');
  const [tipo, setTipo] = useState('');
  const [errors, setErrors] = useState<Errors>({});
  const [mensaje, setMensaje] = useState<Mensaje>(null);
  const [comision, setComision] = useState<string>('');
  const [confirmOpen, setConfirmOpen] = useState(false);

  const validate = (): Errors => {
    const e: Errors = {};

    if (!cuentaOrigen.trim()) e.txtCuentaOrigen = 'Ingrese la cuenta origen';
    else if (!/^\d{10}$/.test(cuentaOrigen)) e.txtCuentaOrigen = 'La cuenta tiene 10 dígitos';

    if (!cuentaDestino.trim()) e.txtCuentaDestino = 'Ingrese la cuenta destino';

    if (!monto.trim()) e.txtMonto = 'Ingrese el monto';
    else {
      const n = parseMonto(monto);
      if (Number.isNaN(n) || n < 1 || n > 10000) e.txtMonto = 'El monto va de 1 a 10.000';
    }
    return e;
  };

  // Illustrative commission for the prototype only (0,5 % of the amount).
  const calcComision = () => formatUsd(parseMonto(monto) * 0.005);

  const submit = () => {
    const e = validate();
    setErrors(e);
    if (Object.keys(e).length > 0) {
      setComision('');
      setMensaje({ tone: 'error', text: 'Revise los campos marcados antes de continuar.' });
      return;
    }
    setComision(calcComision());
    setMensaje(null);
    setConfirmOpen(true);
  };

  const confirm = () => {
    setConfirmOpen(false);
    setMensaje({ tone: 'success', text: 'Transferencia registrada correctamente.' });
    navigate('SCR-COMPROBANTE');
  };

  const cancel = () => {
    setCuentaOrigen('');
    setCuentaDestino('');
    setMonto('');
    setTipo('');
    setErrors({});
    setComision('');
    setMensaje({ tone: 'info', text: 'Operación cancelada. Volvería a Inicio.' });
  };

  return (
    <Screen
      title="Transferencia entre cuentas"
      code="SCR-TRANSFERENCIA"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Transferir', onPress: submit, primary: true },
            { key: 'PF3', label: 'Cancelar', onPress: cancel },
          ]}
        />
      }
    >
      <Stack>
        <Card
          title="Datos de la transferencia"
          actions={<Badge>Campos con * son obligatorios</Badge>}
        >
          <Stack>
            <Grid columns={2}>
              <div data-field="txtCuentaOrigen">
                <TextField
                  label="Cuenta origen"
                  required
                  numeric
                  maxLength={10}
                  hint="10 dígitos"
                  value={cuentaOrigen}
                  error={errors.txtCuentaOrigen}
                  onChange={(v: string) => setCuentaOrigen(v.replace(/\D/g, '').slice(0, 10))}
                />
              </div>
              <div data-field="txtCuentaDestino">
                <TextField
                  label="Cuenta destino"
                  required
                  maxLength={10}
                  value={cuentaDestino}
                  error={errors.txtCuentaDestino}
                  onChange={(v: string) => setCuentaDestino(v.slice(0, 10))}
                />
              </div>
              <div data-field="txtMonto">
                <TextField
                  label="Monto (USD)"
                  required
                  numeric
                  maxLength={9}
                  hint="Entre 1 y 10.000"
                  value={monto}
                  error={errors.txtMonto}
                  onChange={(v: string) => {
                    const clean = v.replace(/[^\d.,]/g, '');
                    const first = clean.search(/[.,]/);
                    const single =
                      first === -1
                        ? clean
                        : clean.slice(0, first + 1) + clean.slice(first + 1).replace(/[.,]/g, '');
                    setMonto(single.slice(0, 9));
                  }}
                />
              </div>
              <div data-field="ddlTipo">
                <SelectField
                  label="Tipo"
                  options={TIPOS}
                  value={tipo}
                  onChange={(v: string) => setTipo(v)}
                />
              </div>
            </Grid>
          </Stack>
        </Card>

        <Card title="Resultado">
          <Stack>
            <div data-field="lblComision">
              <Row>
                <strong>Comisión:</strong>
                <span>{comision || '—'}</span>
                <Badge>Estimación de ejemplo</Badge>
              </Row>
            </div>
            <div data-field="lblMensaje" aria-live="polite">
              {mensaje ? (
                <Alert tone={mensaje.tone}>{mensaje.text}</Alert>
              ) : (
                <Alert tone="info">Complete los datos y presione Transferir.</Alert>
              )}
            </div>
          </Stack>
        </Card>

        <Row>
          <Button variant="primary" onClick={submit}>
            Transferir
          </Button>
          <Button variant="secondary" onClick={cancel}>
            Cancelar
          </Button>
        </Row>
      </Stack>

      <Modal title="Confirmar transferencia" open={confirmOpen} onClose={() => setConfirmOpen(false)}>
        <Stack>
          <p>Cuenta origen: {cuentaOrigen}</p>
          <p>Cuenta destino: {cuentaDestino}</p>
          <p>Monto: {monto && formatUsd(parseMonto(monto))}</p>
          <p>Tipo: {tipo || 'Sin especificar'}</p>
          <p>Comisión: {comision}</p>
          <Row>
            <Button variant="primary" onClick={confirm}>
              Confirmar
            </Button>
            <Button variant="ghost" onClick={() => setConfirmOpen(false)}>
              Volver
            </Button>
          </Row>
        </Stack>
      </Modal>
    </Screen>
  );
}
