```tsx
import { useState } from 'react'
import type { FormEvent } from 'react'
import { Screen, Card, Grid, Stack, TextField, SelectField, Button, Alert } from '@nexti/ds'
import { ApiError } from '../api/client'
import type { ScreenProps } from './types'

type Errors = {
  txtCuentaOrigen?: string
  txtCuentaDestino?: string
  txtMonto?: string
}

type Tone = 'info' | 'success' | 'warning' | 'error'

const TIPOS = [
  { value: '', label: 'Seleccione (opcional)' },
  { value: 'PRO', label: 'PRO' },
  { value: 'INM', label: 'INM' },
]

export default function TransferenciaScreen({ api }: ScreenProps) {
  const [cuentaOrigen, setCuentaOrigen] = useState('')
  const [cuentaDestino, setCuentaDestino] = useState('')
  const [monto, setMonto] = useState('')
  const [tipo, setTipo] = useState('')
  const [errors, setErrors] = useState<Errors>({})
  const [comision, setComision] = useState('')
  const [mensaje, setMensaje] = useState('Complete los datos y presione Transferir.')
  const [tone, setTone] = useState<Tone>('info')
  const [busy, setBusy] = useState(false)

  const submit = async (ev?: FormEvent) => {
    ev?.preventDefault()
    if (busy) return

    const e: Errors = {}
    if (!cuentaOrigen.trim()) e.txtCuentaOrigen = 'Ingrese la cuenta origen'
    if (!cuentaDestino.trim()) e.txtCuentaDestino = 'Ingrese la cuenta destino'

    let montoNum = NaN
    if (!monto.trim()) {
      e.txtMonto = 'Ingrese el monto'
    } else {
      montoNum = Number(monto.trim().replace(',', '.'))
      if (!Number.isFinite(montoNum)) e.txtMonto = 'El monto no es válido'
    }

    setErrors(e)
    if (Object.keys(e).length > 0) {
      setComision('')
      setTone('error')
      setMensaje('Revise los campos marcados antes de continuar.')
      return
    }

    setBusy(true)
    try {
      const res = await api.realizarTransferencia({
        cuentaOrigen: cuentaOrigen.trim(),
        cuentaDestino: cuentaDestino.trim(),
        monto: montoNum,
        tipo,
      })
      setComision(res.comision)
      setTone('success')
      setMensaje(res.mensaje)
    } catch (err) {
      setComision('')
      setTone('error')
      if (err instanceof ApiError) {
        setMensaje(err.message)
      } else {
        setMensaje('No se pudo completar la operación.')
      }
    } finally {
      setBusy(false)
    }
  }

  const cancel = () => {
    setCuentaOrigen('')
    setCuentaDestino('')
    setMonto('')
    setTipo('')
    setErrors({})
    setComision('')
    setTone('info')
    setMensaje('Operación cancelada.')
  }

  return (
    <Screen title="Transferencia entre cuentas">
      <form onSubmit={submit} noValidate>
        <Stack>
          <Card title="Datos de la transferencia">
            <Grid columns={2}>
              <div data-field="txtCuentaOrigen">
                <TextField
                  label="Cuenta origen"
                  required
                  maxLength={10}
                  value={cuentaOrigen}
                  error={errors.txtCuentaOrigen}
                  onChange={(v: string) => setCuentaOrigen(v.slice(0, 10))}
                />
              </div>
              <div data-field="txtCuentaDestino">
                <TextField
                  label="Cuenta destino"
                  required
                  maxLength={10}
                  value={cuentaDestino}
                  error={errors.txtCuentaDestino}
                  onChange={(v: string) => setCuentaDestino(v.slice(0, 10))}
                />
              </div>
              <div data-field="txtMonto">
                <TextField
                  label="Monto (USD)"
                  required
                  numeric
                  maxLength={9}
                  value={monto}
                  error={errors.txtMonto}
                  onChange={(v: string) => setMonto(v.slice(0, 9))}
                />
              </div>
              <div data-field="ddlTipo">
                <SelectField
                  label="Tipo"
                  options={TIPOS}
                  value={tipo}
                  onChange={(v: string) => setTipo(v.slice(0, 3))}
                />
              </div>
            </Grid>
          </Card>

          <Card title="Resultado">
            <Stack>
              <div>
                <strong>Comisión: </strong>
                <span data-field="lblComision">{comision}</span>
              </div>
              <div aria-live="polite">
                <Alert tone={tone}>
                  <span data-field="lblMensaje">{mensaje}</span>
                </Alert>
              </div>
            </Stack>
          </Card>

          <div>
            <Button variant="primary" type="submit" data-action="ENTER">
              Transferir
            </Button>
            <Button variant="secondary" type="button" data-action="btnCancelar" onClick={cancel}>
              Cancelar
            </Button>
          </div>
        </Stack>
      </form>
    </Screen>
  )
}
